layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
layout(color) uniform half4 amzp_color3;
layout(color) uniform half4 amzp_color4;
layout(color) uniform half4 amzp_color5;
uniform float amzp_stop1;
uniform float amzp_stop2;
uniform float amzp_stop3;
uniform float amzp_stop4;
uniform float amzp_stop5;
uniform float amzp_lumMode;
uniform float amzp_gradGamma;
uniform float amzp_gradContrast;
uniform float amzp_gradBrightness;
uniform float amzp_gradInvert;
uniform float amzp_gradReverse;
uniform float amzp_mapStrength;
uniform float amzp_blendMode;
uniform float amzp_preserveLum;
uniform float amzp_preserveSat;
uniform float amzp_preserveHue;
uniform float amzp_hueShift;
uniform float amzp_satAdjust;
uniform float amzp_lumAdjust;
uniform float amzp_shadowsOnly;
uniform float amzp_midtonesOnly;
uniform float amzp_highlightsOnly;
uniform float amzp_duotoneMode;
layout(color) uniform half4 amzp_duoShadow;
layout(color) uniform half4 amzp_duoHighlight;
uniform float amzp_globalMix;
    float lum709(float3 c) {
        return dot(c, float3(0.2126, 0.7152, 0.0722));
    }
    float getLum(float3 c, float mode) {
        if (mode < 1.5) return dot(c, float3(0.2126, 0.7152, 0.0722));
        if (mode < 2.5) return max(c.r, max(c.g, c.b));
        if (mode < 3.5) return (c.r + c.g + c.b) / 3.0;
        if (mode < 4.5) return pow(dot(pow(max(c, 0.0), float3(2.2)), float3(0.2126, 0.7152, 0.0722)), 1.0 / 2.2);
        if (mode < 5.5) return c.r;
        if (mode < 6.5) return c.g;
        if (mode < 7.5) return c.b;
        float mx = max(c.r, max(c.g, c.b));
        float mn = min(c.r, min(c.g, c.b));
        return (mx + mn) * 0.5;
    }
    float3 rgb2hsl(float3 c) {
        float mx = max(c.r, max(c.g, c.b));
        float mn = min(c.r, min(c.g, c.b));
        float l = (mx + mn) * 0.5;
        float d = mx - mn;
        float s = 0.0;
        float h = 0.0;
        if (d > 0.00001) {
            s = (l > 0.5) ? d / max(2.0 - mx - mn, 0.00001) : d / max(mx + mn, 0.00001);
            if (mx == c.r) { h = (c.g - c.b) / d + (c.g < c.b ? 6.0 : 0.0); }
            else if (mx == c.g) { h = (c.b - c.r) / d + 2.0; }
            else { h = (c.r - c.g) / d + 4.0; }
            h /= 6.0;
        }
        return float3(h, s, l);
    }
    float h2r(float p, float q, float t) {
        if (t < 0.0) t += 1.0;
        if (t > 1.0) t -= 1.0;
        if (t < 1.0/6.0) return p + (q - p) * 6.0 * t;
        if (t < 0.5) return q;
        if (t < 2.0/3.0) return p + (q - p) * (2.0/3.0 - t) * 6.0;
        return p;
    }
    float3 hsl2rgb(float3 c) {
        if (c.y < 0.00001) return float3(c.z);
        float q = (c.z < 0.5) ? c.z * (1.0 + c.y) : c.z + c.y - c.z * c.y;
        float p = 2.0 * c.z - q;
        return float3(h2r(p,q,c.x+1.0/3.0), h2r(p,q,c.x), h2r(p,q,c.x-1.0/3.0));
    }
