        float2 uv = amzScreenNorm();
        float4 original = amzTexture(0, uv);
        float3 rgb = max(original.rgb, 0.0);
        float3 baseRGB = rgb;
        float lm = float(int(amzp_lumMode));
        float t = getLum(rgb, lm);
        if (abs(amzp_gradGamma - 1.0) > 0.00001) {
            t = pow(max(t, 0.0), 1.0 / max(amzp_gradGamma, 0.00001));
        }
        if (abs(amzp_gradContrast) > 0.5) {
            float gc = amzp_gradContrast / 100.0;
            t = clamp((t - 0.5) * (1.0 + gc) + 0.5, 0.0, 1.0);
        }
        if (abs(amzp_gradBrightness) > 0.5) {
            t = clamp(t + amzp_gradBrightness / 100.0 * 0.3, 0.0, 1.0);
        }
        if ((amzp_gradInvert>0.5)) {
            t = 1.0 - t;
        }
        float3 c1 = amzp_color1.rgb;
        float3 c2 = amzp_color2.rgb;
        float3 c3 = amzp_color3.rgb;
        float3 c4 = amzp_color4.rgb;
        float3 c5 = amzp_color5.rgb;
        if ((amzp_gradReverse>0.5)) {
            float3 tmp;
            tmp = c1; c1 = c5; c5 = tmp;
            tmp = c2; c2 = c4; c4 = tmp;
        }
        if ((amzp_duotoneMode>0.5)) {
            c1 = amzp_duoShadow.rgb;
            c2 = mix(amzp_duoShadow.rgb, amzp_duoHighlight.rgb, 0.25);
            c3 = mix(amzp_duoShadow.rgb, amzp_duoHighlight.rgb, 0.5);
            c4 = mix(amzp_duoShadow.rgb, amzp_duoHighlight.rgb, 0.75);
            c5 = amzp_duoHighlight.rgb;
        }
        float3 mapped = sampleGradient(t, c1, c2, c3, c4, c5,
                                     amzp_stop1, amzp_stop2, amzp_stop3, amzp_stop4, amzp_stop5);
        float shadowMask = 1.0 - smoothstep(0.0, 0.4, t);
        float highlightMask = smoothstep(0.6, 1.0, t);
        float midtoneMask = 1.0 - shadowMask - highlightMask;
        midtoneMask = max(midtoneMask, 0.0);
        float zoneMask = shadowMask * amzp_shadowsOnly
                       + midtoneMask * amzp_midtonesOnly
                       + highlightMask * amzp_highlightsOnly;
        mapped = mix(rgb, mapped, zoneMask);
        mapped = mix(rgb, mapped, amzp_mapStrength);
        float3 blended = blendColors(rgb, mapped, float(int(amzp_blendMode)));
        if (amzp_preserveHue > 0.00001) {
            float3 origHSL = rgb2hsl(rgb);
            float3 blendHSL = rgb2hsl(max(blended, 0.0));
            blendHSL.x = mix(blendHSL.x, origHSL.x, amzp_preserveHue);
            blended = hsl2rgb(blendHSL);
        }
        if (amzp_preserveSat > 0.00001) {
            float3 origHSL = rgb2hsl(rgb);
            float3 blendHSL = rgb2hsl(max(blended, 0.0));
            blendHSL.y = mix(blendHSL.y, origHSL.y, amzp_preserveSat);
            blended = hsl2rgb(blendHSL);
        }
        if (amzp_preserveLum > 0.00001) {
            float origLum = lum709(rgb);
            float blendLum = lum709(blended);
            if (blendLum > 0.00001) {
                blended *= mix(1.0, origLum / blendLum, amzp_preserveLum);
            }
        }
        if (abs(amzp_hueShift) > 0.5 || abs(amzp_satAdjust) > 0.5 || abs(amzp_lumAdjust) > 0.5) {
            float3 hsl = rgb2hsl(max(blended, 0.0));
            if (abs(amzp_hueShift) > 0.5) {
                hsl.x = fract(hsl.x + amzp_hueShift / 360.0);
            }
            if (abs(amzp_satAdjust) > 0.5) {
                hsl.y = clamp(hsl.y * (1.0 + amzp_satAdjust / 100.0), 0.0, 1.0);
            }
            if (abs(amzp_lumAdjust) > 0.5) {
                hsl.z = clamp(hsl.z + amzp_lumAdjust / 100.0 * 0.3, 0.0, 1.0);
            }
            blended = hsl2rgb(hsl);
        }
        float3 fin = mix(baseRGB, blended, amzp_globalMix);
        fin = clamp(fin, 0.0, 1.0);
        amzOutput = float4(fin, original.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

